import{_ as t,o as n,c as r,a2 as a}from"./chunks/framework.Buc7gXeZ.js";const g=JSON.parse('{"title":"Layout-Blöcke","description":"Blöcke nebeneinander anordnen, in Tabs gliedern und als Schritte führen.","frontmatter":{"title":"Layout-Blöcke","description":"Blöcke nebeneinander anordnen, in Tabs gliedern und als Schritte führen."},"headers":[],"relativePath":"seiten/layout-bloecke.md","filePath":"seiten/layout-bloecke.md","lastUpdated":1786088384000}'),i={name:"seiten/layout-bloecke.md"};function s(o,e,d,l,h,u){return n(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="layout-blocke" tabindex="-1">Layout-Blöcke <a class="header-anchor" href="#layout-blocke" aria-label="Permalink to &quot;Layout-Blöcke&quot;">​</a></h1><p>Vier Blöcke ordnen andere Blöcke an. Sie sind das Gerüst jeder Seite, die über eine reine Textfolge hinausgeht.</p><table tabindex="0"><thead><tr><th>Block</th><th>Zweck</th></tr></thead><tbody><tr><td><strong>Horizontales Layout</strong></td><td><em>Blocks nebeneinander anordnen</em></td></tr><tr><td><strong>Vertikales Layout</strong></td><td><em>Blocks untereinander anordnen</em></td></tr><tr><td><strong>Tab-Layout</strong></td><td><em>Unterseiten als Tabs anzeigen</em></td></tr><tr><td><strong>Stepper-Layout</strong></td><td><em>Unterseiten als Schritte anzeigen</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Im Strukturmodus arbeiten</p><p>Sobald Sie Layouts verschachteln, ist im normalen Editor schwer zu erkennen, welcher Block in welchem liegt. Blenden Sie über <strong>Strukturmodus anzeigen</strong> die <strong>Seitenstruktur</strong> ein. → <a href="/docs/seiten/seite-erstellen">Seite erstellen</a></p></div><hr><h2 id="horizontales-und-vertikales-layout" tabindex="-1">Horizontales und vertikales Layout <a class="header-anchor" href="#horizontales-und-vertikales-layout" aria-label="Permalink to &quot;Horizontales und vertikales Layout&quot;">​</a></h2><p>Beide funktionieren gleich, nur in unterschiedlicher Richtung.</p><h3 id="anordnung" tabindex="-1">Anordnung <a class="header-anchor" href="#anordnung" aria-label="Permalink to &quot;Anordnung&quot;">​</a></h3><p>Unter <strong>Anordnung</strong> stellen Sie ein:</p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Auswahl</th></tr></thead><tbody><tr><td>Richtung</td><td><em>Nebeneinander</em> / <em>Untereinander</em></td></tr><tr><td>Ausrichtung</td><td><em>Start</em>, <em>Center</em>, <em>End</em>, <em>Oben</em>, <em>Unten</em></td></tr><tr><td>Verteilung</td><td><em>Abstand dazwischen</em>, <em>Strecken</em>, <em>Wrap Content</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">„Wrap Content&quot; für Mobilgeräte</p><p>Ohne diese Einstellung bleiben nebeneinanderliegende Blöcke auch auf schmalen Bildschirmen nebeneinander und werden gequetscht. Mit <em>Wrap Content</em> rutschen sie bei zu wenig Platz untereinander.</p><p>Prüfen Sie das Ergebnis in der Portal-Vorschau unter <em>Smartphone</em>.</p></div><h3 id="aussehen" tabindex="-1">Aussehen <a class="header-anchor" href="#aussehen" aria-label="Permalink to &quot;Aussehen&quot;">​</a></h3><p>Zusätzlich verfügbar: <strong>Hintergrundfarbe</strong>, <strong>Border radius</strong>, <strong>Breite</strong> und <strong>Höhe</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Karten bauen</p><p>Ein vertikales Layout mit Hintergrundfarbe und Border radius ergibt eine Karte. Mehrere davon in einem horizontalen Layout ergeben eine Kartenzeile — die übliche Grundlage für Dashboards.</p></div><hr><h2 id="tab-layout" tabindex="-1">Tab-Layout <a class="header-anchor" href="#tab-layout" aria-label="Permalink to &quot;Tab-Layout&quot;">​</a></h2><p>Zeigt <strong>Unterseiten</strong> als Reiter.</p><table tabindex="0"><thead><tr><th>Aktion</th><th>Beschriftung</th></tr></thead><tbody><tr><td>Seite anlegen</td><td><strong>Seite hinzufügen</strong></td></tr><tr><td>Seite entfernen</td><td><strong>Ausgewählte Seite löschen</strong></td></tr><tr><td>Reihenfolge ändern</td><td><strong>Nach links verschieben</strong> / <strong>Nach rechts verschieben</strong></td></tr><tr><td>Farbe</td><td><strong>Tab Farbe</strong></td></tr></tbody></table><p>Ohne Unterseiten erscheint <em>Keine Seiten</em> mit dem Hinweis <em>Fügen Sie Seiten hinzu, um sie als Tabs zu sehen</em>.</p><p>Enthält ein Tab unvollständige Pflichtfelder, meldet der Editor <em>Dieser Tab enthält Validierungsfehler</em>.</p><div class="tip custom-block"><p class="custom-block-title">Wofür Tabs taugen</p><p>Für Bereiche, die <strong>unabhängig</strong> voneinander sind und in beliebiger Reihenfolge angesehen werden — „Übersicht&quot;, „Details&quot;, „Dokumente&quot;.</p><p>Für einen Ablauf mit Reihenfolge nehmen Sie stattdessen das Stepper-Layout.</p></div><hr><h2 id="stepper-layout" tabindex="-1">Stepper-Layout <a class="header-anchor" href="#stepper-layout" aria-label="Permalink to &quot;Stepper-Layout&quot;">​</a></h2><p>Zeigt <strong>Unterseiten</strong> als aufeinanderfolgende Schritte — für geführte Abläufe.</p><table tabindex="0"><thead><tr><th>Aktion</th><th>Beschriftung</th></tr></thead><tbody><tr><td>Schritt anlegen</td><td><strong>Schritt hinzufügen</strong></td></tr><tr><td>Schritt entfernen</td><td><strong>Ausgewählten Schritt löschen</strong></td></tr><tr><td>Reihenfolge ändern</td><td><strong>Nach oben verschieben</strong> / <strong>Nach unten verschieben</strong></td></tr></tbody></table><p>Ohne Schritte: <em>Keine Schritte</em> mit dem Hinweis <em>Fügen Sie Schritte hinzu, um sie im Stepper zu sehen</em>.</p><p>Besucher navigieren mit <strong>Zurück</strong> und <strong>Weiter</strong>.</p><h3 id="zwei-einstellungen" tabindex="-1">Zwei Einstellungen <a class="header-anchor" href="#zwei-einstellungen" aria-label="Permalink to &quot;Zwei Einstellungen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Einstellung</th><th>Beschreibung in der Oberfläche</th></tr></thead><tbody><tr><td><strong>Linear</strong></td><td><em>Vorherige Schritte müssen zuerst abgeschlossen werden</em></td></tr><tr><td><strong>Vertikal</strong></td><td><em>Schritte im vertikalen Modus anzeigen</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Linear für Prozesse, nicht für Formulare</p><p><strong>Linear</strong> erzwingt die Reihenfolge — sinnvoll bei Anträgen, Onboarding und allem, wo ein späterer Schritt auf einem früheren aufbaut.</p><p>Ohne <em>Linear</em> können Besucher springen. Das ist angenehmer, wenn die Schritte nur der Gliederung dienen.</p></div><p>Unvollständige Pflichtfelder melden <em>Dieser Schritt enthält Validierungsfehler</em>.</p><hr><h2 id="welches-layout-wofur" tabindex="-1">Welches Layout wofür <a class="header-anchor" href="#welches-layout-wofur" aria-label="Permalink to &quot;Welches Layout wofür&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ziel</th><th>Layout</th></tr></thead><tbody><tr><td>Kennzahlen nebeneinander</td><td><strong>Horizontales Layout</strong> mit <em>Wrap Content</em></td></tr><tr><td>Karte mit Rahmen und Farbe</td><td><strong>Vertikales Layout</strong> mit Hintergrundfarbe</td></tr><tr><td>Mehrere unabhängige Bereiche</td><td><strong>Tab-Layout</strong></td></tr><tr><td>Geführter Ablauf mit Reihenfolge</td><td><strong>Stepper-Layout</strong>, <em>Linear</em></td></tr><tr><td>Gliederung ohne Zwang</td><td><strong>Stepper-Layout</strong> ohne <em>Linear</em></td></tr><tr><td>Lange Textseite</td><td>keine Layouts, nur Überschriften</td></tr></tbody></table><h2 id="beispiel-dashboard-aufbau" tabindex="-1">Beispiel: Dashboard-Aufbau <a class="header-anchor" href="#beispiel-dashboard-aufbau" aria-label="Permalink to &quot;Beispiel: Dashboard-Aufbau&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vertikales Layout</span></span>
<span class="line"><span>├── Überschrift 1                „Vertrieb&quot;</span></span>
<span class="line"><span>├── Horizontales Layout          (Wrap Content aktiv)</span></span>
<span class="line"><span>│   ├── Zähler                   offene Anfragen</span></span>
<span class="line"><span>│   ├── Summenkarte              Auftragswert</span></span>
<span class="line"><span>│   └── Donut-Diagramm           nach Status</span></span>
<span class="line"><span>└── Grid Ansicht                 Detailtabelle</span></span></code></pre></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/seiten/bloecke">Blockübersicht</a></li><li><a href="/docs/seiten/seitenlayout">Seitenlayout</a></li><li><a href="/docs/seiten/auswertungen">Ansichten und Auswertungen einbetten</a></li></ul>`,38)])])}const b=t(i,[["render",s]]);export{g as __pageData,b as default};
